"""Independent S5 references: R 4.3.3 golden values (tests/fixtures/s5-r-golden.json, regenerated by scripts/s5-r-golden.py),
NIST StRD Longley / Wampler 1-2, exact rational WLS/OLS, and closed-form robust covariances. Nothing here calls pycli code."""
import json, math, pathlib
from fractions import Fraction as F
import numpy as np

ROOT = pathlib.Path(__file__).resolve().parents[2]
GOLDEN = json.loads((ROOT / 'tests/fixtures/s5-r-golden.json').read_text())
DATA, R = GOLDEN['data'], GOLDEN['r']


def columns(*names):
    return {name: DATA[name] for name in names}


def lre(computed, certified):
    error = abs(float(computed) - float(certified))
    return 15.0 if error == 0 else min(15.0, -math.log10(error / abs(float(certified))))


# NIST StRD Longley: certified values (15 digits). Data and coefficients are the S1 oracle's; standard errors,
# residual standard deviation and R^2 are the remaining certified values.
LONGLEY_SE = [890420.383607373, 84.9149257747669, 0.334910077722432e-1, 0.488399681651699, 0.214274163161675, 0.226073200069370, 455.478499142212]
LONGLEY_SIGMA = 304.854073561965
LONGLEY_R2 = 0.995479004577296


def wls_exact(X, y, w):
    """Exact weighted least squares over Q: returns (beta, cov-unscaled diag, rss, sigma2) as Fractions."""
    n, p = len(X), len(X[0])
    A = [[sum(F(w[k]) * F(X[k][i]) * F(X[k][j]) for k in range(n)) for j in range(p)] for i in range(p)]
    b = [sum(F(w[k]) * F(X[k][i]) * F(y[k]) for k in range(n)) for i in range(p)]
    aug = [A[i] + [F(int(i == j)) for j in range(p)] + [b[i]] for i in range(p)]
    for c in range(p):
        pivot = next(r for r in range(c, p) if aug[r][c] != 0)
        aug[c], aug[pivot] = aug[pivot], aug[c]
        lead = aug[c][c]
        aug[c] = [v / lead for v in aug[c]]
        for r in range(p):
            if r != c and aug[r][c] != 0:
                factor = aug[r][c]
                aug[r] = [a - factor * v for a, v in zip(aug[r], aug[c])]
    inverse = [row[p:2 * p] for row in aug]
    beta = [row[2 * p] for row in aug]
    rss = sum(F(w[k]) * (F(y[k]) - sum(beta[i] * F(X[k][i]) for i in range(p))) ** 2 for k in range(n))
    return beta, inverse, rss, rss / (n - p)


def sandwich(X, resid, kind, groups=None):
    """Closed-form robust covariance of OLS (numpy only): HC0..HC3 and one-way cluster with statsmodels' small-sample factors."""
    X = np.asarray(X, float)
    e = np.asarray(resid, float)
    n, p = X.shape
    bread = np.linalg.inv(X.T @ X)
    h = np.einsum('ij,jk,ik->i', X, bread, X)
    if kind == 'cluster':
        meat = np.zeros((p, p))
        labels = sorted(set(groups))
        for label in labels:
            idx = [i for i, g in enumerate(groups) if g == label]
            s = X[idx].T @ e[idx]
            meat += np.outer(s, s)
        g = len(labels)
        correction = g / (g - 1.0) * (n - 1.0) / (n - p)
        return bread @ meat @ bread * correction
    weights = {'HC0': e ** 2, 'HC1': e ** 2 * n / (n - p), 'HC2': e ** 2 / (1 - h), 'HC3': e ** 2 / (1 - h) ** 2}[kind]
    return bread @ (X.T * weights) @ X @ bread
